#!/usr/bin/env node
// Derives the ephemeral MRT preview target slug for a branch name. Shared by
// deploy-preview.yml and teardown-preview.yml so both compute the identical slug
// for a given branch — teardown must find exactly what deploy created, and two
// independently-maintained copies of this logic would eventually drift.
//
// Usage: node scripts/computeMrtPreviewSlug.mjs '<branch-name>'
// Prints the slug to stdout on success. Exits 1 with a message on stderr if no
// valid, non-empty slug can be derived.

import { createHash } from 'node:crypto';

// Hard MRT API limit, confirmed live: POSTing a longer name 400s with
// {"slug":"Target names can be at most 19 characters."} — not a DNS-label
// assumption, an actual enforced constraint. This leaves very little room, so
// every character below is deliberately budgeted.
const MAX_SLUG_LEN = 19;
const PREFIX = 'pr-'; // required — this is what makes collision with the fixed
// named tiers (dev, test, sit, uat, stg, production, dev1) structurally
// impossible, so it isn't a place to economize further.

// A digest of the full, untransformed branch name is appended to every slug,
// not just ones long enough to need truncating — the readable part alone is a
// lossy normalization (punctuation collapses, the Jira key is stripped from
// wherever it appears, and there's barely any room for it besides) and can
// collide for distinct branch names, e.g. `feature/checkout-header` and
// `feature/checkout_header`. The digest is what makes collisions between
// distinct branch names astronomically unlikely — not impossible, since it's
// a hash, not a reversible encoding — while the readable part is purely for
// browsing Runtime Admin. Accepted residual risk: a true collision would need
// two distinct branch names to share the same digest, which no realistic
// number of concurrent preview branches will ever approach. 8 hex chars (32
// bits) is the most this 19-char budget can spare it while still leaving room
// for anything human-readable at all.
const HASH_LEN = 8;
const STEM_LEN = MAX_SLUG_LEN - PREFIX.length - HASH_LEN - 1; // -1 for the hyphen before the hash

const branch = process.argv[2];

const die = (msg) => {
  console.error(`✗ computeMrtPreviewSlug: ${msg}`);
  process.exit(1);
};

if (!branch) die('usage: computeMrtPreviewSlug.mjs <branch-name>');

const jiraMatch = branch.match(/SFCC-(\d+)/i);

// A single-char kind marker (not "ft"/"fx" — no room to spare) is still
// enough to keep feature/SFCC-123-x and fix/SFCC-123-x from colliding on the
// readable part, which otherwise strips the feature/fix prefix entirely.
const prefixMatch = branch.match(/^(feature|fix)\//);
const kind = prefixMatch ? (prefixMatch[1] === 'feature' ? 'f' : 'x') : '';

const withoutPrefix = branch.replace(/^(feature|fix)\//, '').replace(/SFCC-\d+/i, '');
const sanitized = withoutPrefix
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '');

// Prefer the Jira ticket number over the free-text remainder when both are
// present — it's the more useful thing to recognize at a glance with only a
// handful of characters to spend, and this repo's branch convention always
// carries one when a story exists.
let content;
if (jiraMatch) {
  content = jiraMatch[1];
} else {
  if (!sanitized) die(`branch "${branch}" sanitizes to an empty slug — refusing to proceed`);
  content = sanitized;
}

const stem = `${kind}${content}`.slice(0, STEM_LEN).replace(/^-|-$/g, '');
const hash = createHash('sha256').update(branch).digest('hex').slice(0, HASH_LEN);

console.log(`${PREFIX}${stem}-${hash}`);

